{{
  // Hoy
  const until = $now.toFormat('yyyy-MM-dd');
  // Hoy menos 2 días (para cubrir un rango de 3 días en total)
  const since = $now.minus({ days: 7 }).toFormat('yyyy-MM-dd');
  // Devuelve el objeto en el formato que la API necesita
  return { since, until };
}}

// --- CONFIGURACIÓN DE UMBRALES ---
const UMBRALES = {
  COSTE_POR_ACCION_MAX: 16.00,
  COSTE_POR_ACCION_MIN: 10.00,
  DIAS_MIN_ANTIGUEDAD: 10
};

// --- 1. OBTENER DATOS DE NODOS ANTERIORES ---
let nombreCliente = "N/A", nombreEmpresa = "N/A", idCuentaPublicitaria = "N/A", esAlertaRepetida = false;
let idUsuarioSlack = "";
let mensajeEspecialEstratega = ""; // [CAMBIO CLAVE] Variable para el mensaje de estratega no encontrado

try {
  const datosEstratega = $input.first().json;
  const mensajeEstratega = datosEstratega.mensaje || "";

  // [CAMBIO CLAVE] Detecta si es la frase de advertencia
  if (mensajeEstratega.includes("No existe un estratega registrado")) {
    mensajeEspecialEstratega = mensajeEstratega; // Guarda la frase completa
  }

  // La extracción del ID sigue funcionando para ambos casos
  const match = mensajeEstratega.match(/<@(.*?)>/);
  idUsuarioSlack = (match && match[0]) ? match[0] : "equipo";

} catch (error) {
  idUsuarioSlack = "equipo";
}

try {
  const datosEntrantes = $('Data-entrante3').first().json.data;
  nombreCliente = datosEntrantes.nombre;
  nombreEmpresa = datosEntrantes.empresa || "No encontrado";
  idCuentaPublicitaria = datosEntrantes["ID-cuenta-publicitaria"] || "No encontrado";
  if (datosEntrantes.status === 'repetido') {
    esAlertaRepetida = true;
  }
} catch (error) {
  // Usar valores por defecto.
}

// --- 2. PROCESAR CAMPAÑAS ---
let campaigns = [];
const inputJson = $('Aggregate3').first().json;

if (Array.isArray(inputJson) && inputJson.length > 0 && inputJson[0].data) {
  campaigns = inputJson[0].data;
} else if (inputJson && inputJson.data) {
  campaigns = inputJson.data;
}

const campaignAlertBlocks = [];

for (const campaign of campaigns) {
  let estadoFinal, motivoFinal;

  const ahora = new Date($now.toISO());
  const fechaCreacion = new Date(campaign.created_time);
  const fechaLimite = new Date(ahora);
  fechaLimite.setDate(ahora.getDate() - UMBRALES.DIAS_MIN_ANTIGUEDAD);

  if (fechaCreacion >= fechaLimite) {
    estadoFinal = 'Fuera de pool de alertas';
  } else {
    const metrics = campaign.insights?.data[0];
    if (!metrics) {
      estadoFinal = 'REQUIERE REVISIÓN';
      motivoFinal = 'No se encontraron datos de métricas. Posible error de entrega.';
    } else {
      let esCampanaAnalizable = false;
      if (metrics.cost_per_result && metrics.cost_per_result.length > 0) {
        for (const result of metrics.cost_per_result) {
          const actionType = result.indicator || "";
          if (actionType.includes('messaging_conversation') || actionType.includes('lead')) {
            esCampanaAnalizable = true;
            break;
          }
        }
      }

      if (!esCampanaAnalizable) {
        estadoFinal = 'No Analizable';
      } else {
        const alertas = [];
        for (const result of metrics.cost_per_result) {
          if (result.values && result.values.length > 0) {
            const costValue = parseFloat(result.values[0].value);
            const actionType = result.indicator || "";
            const tipo = actionType.includes('lead') ? 'Lead' : 'Conversación';

            if (actionType.includes('messaging_conversation') || actionType.includes('lead')) {
              if (costValue > UMBRALES.COSTE_POR_ACCION_MAX) {
                alertas.push(`Costo por ${tipo} alto ($${costValue.toFixed(2)})`);
              } else if (costValue < UMBRALES.COSTE_POR_ACCION_MIN) {
                alertas.push(`Costo por ${tipo} bajo ($${costValue.toFixed(2)})`);
              }
            }
          }
        }

        if (alertas.length > 0) {
          estadoFinal = 'REQUIERE REVISIÓN';
          motivoFinal = alertas.join(', ');
        } else {
          estadoFinal = 'OK';
        }
      }
    }
  }

  if (estadoFinal === 'REQUIERE REVISIÓN') {
    const fechaCreacionObj = new Date(campaign.created_time);
    const opcionesFormato = { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' };
    const fechaFormateada = fechaCreacionObj.toLocaleDateString('es-ES', opcionesFormato);

    const campaignSection = {
      "type": "section",
      "text": { "type": "mrkdwn", "text": `*Campaña:* ${campaign.name}\n*Fecha de creación:* ${fechaFormateada}\n*Estado:* \`${estadoFinal}\`\n*Razón:* ${motivoFinal}` }
    };
    const divider = { "type": "divider" };
    campaignAlertBlocks.push(campaignSection, divider);
  }
}

// --- 3. ENSAMBLAJE FINAL DEL REPORTE Y DEL JSON DE SLACK ---
let estadoGeneral = "";
let slackBlock = null;

if (campaignAlertBlocks.length > 0) {
  estadoGeneral = "Reporte Existente";

  let textoIntroduccion;
  if (esAlertaRepetida) {
    textoIntroduccion = `Hola ${idUsuarioSlack}, esta alerta *sigue activa* y requiere tu atención.`;
  } else {
    textoIntroduccion = `Hola ${idUsuarioSlack}, se ha detectado una *nueva alerta* que requiere tu atención.`;
  }

  // [CAMBIO CLAVE] Se crea un bloque de contexto si hay un mensaje especial
  const extraBlocks = [];
  if (mensajeEspecialEstratega) {
    extraBlocks.push({
      "type": "context",
      "elements": [{ "type": "mrkdwn", "text": `*Nota:* ${mensajeEspecialEstratega}` }]
    });
    extraBlocks.push({ "type": "divider" });
  }

  slackBlock = {
    "blocks": [
      {
        "type": "header",
        "text": { "type": "plain_text", "text": esAlertaRepetida ? "🚨 ALERTA REPETIDA 🚨" : "🚨 Alerta de Campaña Nueva", "emoji": true }
      },
      {
        "type": "section",
        "text": { "type": "mrkdwn", "text": textoIntroduccion }
      },
      { "type": "divider" },
      {
        "type": "section",
        "fields": [
          { "type": "mrkdwn", "text": `*Cliente:*\n${nombreCliente}` },
          { "type": "mrkdwn", "text": `*Empresa:*\n${nombreEmpresa}` },
          { "type": "mrkdwn", "text": `*ID Cuenta Publicitaria:*\n${idCuentaPublicitaria}` }
        ]
      },
      // [CAMBIO CLAVE] Se insertan los bloques extra aquí
      ...extraBlocks,
      ...campaignAlertBlocks,
      {
        "type": "actions",
        "elements": [
          { "type": "button", "text": { "type": "plain_text", "text": "Campañas Ajustadas", "emoji": true }, "style": "primary", "value": "revisado", "action_id": "approve_button" },
          { "type": "button", "text": { "type": "plain_text", "text": "Dependencia", "emoji": true }, "value": "dependencia", "action_id": "dependencia_button" }
        ]
      }
    ]
  };

} else {
  estadoGeneral = "Todo OK";
}

return [{
  json: {
    estado_general: estadoGeneral,
    slack_block: slackBlock
  }
}];

